```javascript
function estPalindrome(s) {
    const reversed = s.split('').reverse().join('');
    return s === reversed;
}

function pgcd(a, b) {
    while (b !== 0) {
        let temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

function nombreMots(s) {
    const trimmed = s.trim();
    if (trimmed.length === 0) {
        return 0;
    }
    return trimmed.split(/\s+/).length;
}

function fusionTriee(a, b) {
    let result = [];
    let i = 0;
    let j = 0;

    while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
            result.push(a[i]);
            i++;
        } else {
            result.push(b[j]);
            j++;
        }
    }

    while (i < a.length) {
        result.push(a[i]);
        i++;
    }

    while (j < b.length) {
        result.push(b[j]);
        j++;
    }

    return result;
}

function sontAnagrammes(a, b) {
    if (a.length !== b.length) {
        return false;
    }
    const sortedA = a.split('').sort().join('');
    const sortedB = b.split('').sort().join('');
    return sortedA === sortedB;
}
```

