```javascript
function dernierElement(tableau) {
    if (tableau.length === 0) {
        return undefined;
    }
    return tableau[tableau.length - 1];
}

function compterJusqua(n) {
    if (n < 1) {
        return [];
    }
    let result = [];
    for (let i = 1; i <= n; i++) {
        result.push(i);
    }
    return result;
}

function remplacerLettre(mot, ancienne, nouvelle) {
    if (!ancienne || !nouvelle) {
        return mot;
    }
    let resultat = "";
    for (let i = 0; i < mot.length; i++) {
        if (mot[i] === ancienne) {
            resultat += nouvelle;
        } else {
            resultat += mot[i];
        }
    }
    return resultat;
}

function sommeTableau(tableau) {
    let somme = 0;
    for (let i = 0; i < tableau.length; i++) {
        somme += tableau[i];
    }
    return somme;
}

function contientA(mot) {
    mot = mot.toLowerCase();
    for (let i = 0; i < mot.length; i++) {
        if (mot[i] === 'a') {
            return true;
        }
    }
    return false;
}

function validerParentheses(s) {
    let stack = [];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            stack.push('(');
        } else if (s[i] === ')') {
            if (stack.length === 0) {
                return false;
            }
            stack.pop();
        }
    }
    return stack.length === 0;
}

function fibonacci(n) {
    if (n < 0) {
        throw new Error("n must be non-negative");
    }
    let a = 0, b = 1;
    for (let i = 2; i <= n; i++) {
        [a, b] = [b, a + b];
    }
    return b;
}

function motsUniques(s) {
    if (!s || s.trim() === "") {
        return 0;
    }
    let mots = s.split(/\s+/);
    let set = new Set(mots);
    return set.size;
}

function aplatirTableau(tab) {
    if (!tab || tab.length === 0) {
        return [];
    }
    let result = [];
    for (let i = 0; i < tab.length; i++) {
        if (Array.isArray(tab[i])) {
            for (let j = 0; j < tab[i].length; j++) {
                result.push(tab[i][j]);
            }
        } else {
            result.push(tab[i]);
        }
    }
    return result;
}

function rotationDroite(tab, k) {
    if (!tab || tab.length === 0) {
        return [];
    }
    let n = tab.length;
    k = k % n;
    if (k === 0) {
        return [...tab];
    }
    let resultat = new Array(n);
    for (let i = 0; i < n; i++) {
        resultat[(i + k) % n] = tab[i];
    }
    return resultat;
}
```

